/* ================= BOOKING FORMS ================= */
function localDateISO() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`; /* local date, not UTC */
}

function buildTruckSelect() {
  const sel = $("truckSelect");
  const labels = { lcv: "Mini / LCV", container: "Closed container trucks", open: "Open body lorries", trailer: "Heavy trailers" };
  sel.innerHTML = FLEET_GROUP_ORDER.map((cat) => {
    const opts = FLEET_DATA.filter((v) => v.category === cat)
      .map((v) => `<option value="${escapeHtml(v.select)}">${escapeHtml(v.select)}</option>`).join("");
    return `<optgroup label="${labels[cat]}">${opts}</optgroup>`;
  }).join("");
  sel.value = "32 ft Container MXL (15–18 Tonnes)";
}

function validPhone(value) {
  const digits = value.replace(/\D/g, "");
  return digits.length >= 10 && digits.length <= 13;
}

function initBookingForms() {
  const date = $("pickupDate");
  date.value = localDateISO();
  date.min = localDateISO();

  setupAutocomplete("fromCity", "fromCityList");
  setupAutocomplete("uptoCity", "uptoCityList");
  setupAutocomplete("truckerCurrentCity", "truckerCurrentCityList");
  setupAutocomplete("truckerReturnCity", "truckerReturnCityList");

  $("swapCitiesBtn").addEventListener("click", () => {
    const f = $("fromCity"), u = $("uptoCity");
    [f.value, u.value] = [u.value, f.value];
  });

  $("shipperTab").addEventListener("submit", (e) => {
    e.preventDefault();
    const phone = $("shipperPhone").value.trim();
    if (!validPhone(phone)) {
      showToast("Please enter a valid mobile number (10 digits).");
      $("shipperPhone").focus();
      return;
    }
    const isFTL = $("optFTL").classList.contains("active");
    const loadMode = isFTL ? "Full Load Truck (FTL)" : "Sharing Load (PTL)";
    let detailLabel = "Vehicle";
    let detailValue = $("truckSelect").value;
    if (!isFTL) {
      detailLabel = "Cargo";
      const wt = $("cargoWeight").value.trim() || "Weight to be confirmed";
      const pk = $("cargoPackages").value.trim() || "Packages to be confirmed";
      detailValue = `${wt} · ${pk} · ${$("cargoMaterial").value}`;
    }
    openHandoff("Freight booking summary", "New Freight Booking Request — Sanwaliya Translinks", [
      ["Load mode", loadMode],
      ["From", $("fromCity").value.trim()],
      ["Upto", $("uptoCity").value.trim()],
      [detailLabel, detailValue],
      ["Pickup date", $("pickupDate").value],
      ["Contact phone", phone]
    ]);
  });

  $("truckerTab").addEventListener("submit", (e) => {
    e.preventDefault();
    const phone = $("truckerPhone").value.trim();
    if (!validPhone(phone)) {
      showToast("Please enter a valid WhatsApp number (10 digits).");
      $("truckerPhone").focus();
      return;
    }
    openHandoff("Truck attachment summary", "Truck Availability Registration — Sanwaliya Translinks", [
      ["Request type", "Truck attachment / availability"],
      ["Current city", $("truckerCurrentCity").value.trim()],
      ["Preferred return", $("truckerReturnCity").value.trim() || "Open / any pan-India route"],
      ["Vehicle", $("truckerVehicleType").value],
      ["Registration no.", $("truckerRegNo").value.trim() || "Not provided"],
      ["Driver / owner phone", phone]
    ]);
  });

  initModal();
}

/* ---------- Hand-off modal ---------- */
function openHandoff(heading, subject, rows) {
  $("modalTitle").textContent = heading;
  $("modalDetails").innerHTML = rows
    .map(([k, v]) => `<div class="modal-row"><span>${escapeHtml(k)}</span><strong>${escapeHtml(v)}</strong></div>`)
    .join("");
  lastSummary = [subject, "", ...rows.map(([k, v]) => `${k}: ${v}`)].join("\n");

  setChannel($("whatsappConfirmLink"), whatsappUrl(lastSummary), "WhatsApp number");
  const mail = SITE_CONFIG.DISPATCH_EMAIL.trim();
  setChannel($("emailConfirmLink"),
    mail ? `mailto:${mail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(lastSummary)}` : "",
    "dispatch email");

  lastFocus = document.activeElement;
  $("bookingModal").classList.remove("hidden");
  $("closeModalBtn").focus();
  document.body.style.overflow = "hidden";
}

function closeModal() {
  $("bookingModal").classList.add("hidden");
  document.body.style.overflow = "";
  if (lastFocus && lastFocus.focus) lastFocus.focus();
}

function initModal() {
  const modal = $("bookingModal");
  $("closeModalBtn").addEventListener("click", closeModal);
  modal.addEventListener("click", (e) => { if (e.target === modal) closeModal(); });
  document.addEventListener("keydown", (e) => {
    if (modal.classList.contains("hidden")) return;
    if (e.key === "Escape") closeModal();
    if (e.key === "Tab") {
      const f = modal.querySelectorAll("a[href], button");
      const first = f[0], last = f[f.length - 1];
      if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  });
  $("copySummaryBtn").addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(lastSummary);
      showToast("Summary copied.");
    } catch (err) {
      showToast("Couldn't copy automatically. Please select the text and copy it.");
    }
  });
}

/* ---------- City autocomplete ---------- */
function setupAutocomplete(inputId, listId) {
  const input = $(inputId);
  const list = $(listId);
  let active = -1;

  const close = () => { list.classList.remove("open"); input.setAttribute("aria-expanded", "false"); active = -1; };
  const choose = (value) => { input.value = value; close(); };

  function render() {
    const q = input.value.trim().toLowerCase();
    let matches;
    if (!q) {
      matches = INDIA_CITIES.slice(0, 8);
    } else {
      const starts = INDIA_CITIES.filter((c) => c.toLowerCase().startsWith(q));
      const contains = INDIA_CITIES.filter((c) => !c.toLowerCase().startsWith(q) && c.toLowerCase().includes(q));
      matches = starts.concat(contains).slice(0, 8);
    }
    list.innerHTML = "";
    active = -1;

    if (!matches.length) {
      const raw = input.value.trim();
      const row = document.createElement("div");
      row.className = "ac-item";
      row.setAttribute("role", "option");
      row.innerHTML = `<strong>${escapeHtml(raw)}</strong><span class="ac-state">Use as typed (city / PIN)</span>`;
      row.addEventListener("mousedown", (e) => { e.preventDefault(); choose(raw); });
      list.appendChild(row);
    } else {
      matches.forEach((item) => {
        const i = item.lastIndexOf(", ");
        const row = document.createElement("div");
        row.className = "ac-item";
        row.setAttribute("role", "option");
        row.dataset.value = item;
        row.innerHTML = `<strong>${escapeHtml(item.slice(0, i))}</strong><span class="ac-state">${escapeHtml(item.slice(i + 2))}</span>`;
        row.addEventListener("mousedown", (e) => { e.preventDefault(); choose(item); });
        list.appendChild(row);
      });
    }
    list.classList.add("open");
    input.setAttribute("aria-expanded", "true");
  }

  const mark = (rows) => rows.forEach((r, i) => r.classList.toggle("focused", i === active));

  input.addEventListener("focus", render);
  input.addEventListener("input", render);
  input.addEventListener("blur", () => setTimeout(close, 120));
  input.addEventListener("keydown", (e) => {
    const rows = Array.from(list.querySelectorAll(".ac-item"));
    if (!list.classList.contains("open") || !rows.length) return;
    if (e.key === "ArrowDown") { e.preventDefault(); active = (active + 1) % rows.length; mark(rows); rows[active].scrollIntoView({ block: "nearest" }); }
    else if (e.key === "ArrowUp") { e.preventDefault(); active = (active - 1 + rows.length) % rows.length; mark(rows); rows[active].scrollIntoView({ block: "nearest" }); }
    else if (e.key === "Enter" && active >= 0) { e.preventDefault(); choose(rows[active].dataset.value || input.value.trim()); }
    else if (e.key === "Escape") { close(); }
  });
}

