/* ================= SCROLL REVEAL & COUNTERS ================= */
function initReveal() {
  const els = document.querySelectorAll(".reveal");
  if (!("IntersectionObserver" in window) || reduceMotion) {
    els.forEach((el) => el.classList.add("in"));
    return;
  }
  const io = new IntersectionObserver((entries) => {
    entries.forEach((en) => {
      if (en.isIntersecting) { en.target.classList.add("in"); io.unobserve(en.target); }
    });
  }, { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });
  els.forEach((el) => io.observe(el));
}

function initCounters() {
  const nums = document.querySelectorAll(".count-num");
  $("fleetCountNum").dataset.target = String(FLEET_DATA.length);
  $("fleetCountNum").textContent = String(FLEET_DATA.length);

  const run = (el) => {
    const target = Number(el.dataset.target || 0);
    if (reduceMotion) { el.textContent = String(target); return; }
    const start = performance.now();
    const dur = 1100;
    const step = (now) => {
      const p = Math.min(1, (now - start) / dur);
      el.textContent = String(Math.round(target * (1 - Math.pow(1 - p, 3))));
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  };

  if (!("IntersectionObserver" in window)) return;
  if (!reduceMotion) nums.forEach((el) => { el.textContent = "0"; });
  const io = new IntersectionObserver((entries) => {
    entries.forEach((en) => {
      if (en.isIntersecting) { run(en.target); io.unobserve(en.target); }
    });
  }, { threshold: 0.6 });
  nums.forEach((el) => io.observe(el));
}

/* ================= TOAST ================= */
function showToast(message) {
  const toast = $("toast");
  toast.textContent = message;
  toast.classList.remove("hidden");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.add("hidden"), 3400);
}

/* ================= SCROLL ROAD (truck travels along the header as you scroll) ================= */
function initScrollRoad() {
  const bar = document.querySelector(".scroll-road");
  if (!bar) return;
  let queued = false;
  const update = () => {
    const max = document.documentElement.scrollHeight - window.innerHeight;
    bar.style.setProperty("--p", max > 0 ? Math.min(1, window.scrollY / max).toFixed(4) : "0");
    queued = false;
  };
  let idle;
  window.addEventListener("scroll", () => {
    bar.classList.add("moving"); clearTimeout(idle); idle = setTimeout(() => bar.classList.remove("moving"), 160); /* wheels turn only while scrolling */
    if (!queued) { queued = true; requestAnimationFrame(update); }
  }, { passive: true });
  window.addEventListener("resize", update);
  update();
}

/* ================= TRUCK ARTWORK (side view, spinning wheels) ================= */
function truckSVG(cls, branded, smoke) {
  const wheel = (x) => `<g transform="translate(${x} 40)"><g class="wheel"><circle r="6.6" fill="#121722"/><circle r="3.1" fill="#B9C2D0"/><path d="M0-4.8V4.8M-4.8 0H4.8" stroke="#121722" stroke-width="1.2"/></g></g>`;
  const ribs = [10, 18, 26, 34, 42, 50, 58, 66, 74].map((x) => `M${x} 3v31`).join("");
  return `<svg class="${cls}" viewBox="0 0 120 50" overflow="visible" aria-hidden="true">
    ${smoke ? '<circle class="smoke" cx="81.5" cy="-2" r="2.6" fill="#fff"/><circle class="smoke s2" cx="81.5" cy="-2" r="2.6" fill="#fff"/>' : ""}
    <rect x="2" y="3" width="76" height="31" rx="3" fill="var(--tb,#F2EFE8)"/>
    <path d="${ribs}" stroke="var(--tr,rgba(0,0,0,.13))" stroke-width="1.6"/>
    <rect x="2" y="23" width="76" height="4.5" fill="var(--accent)"/>
    ${branded ? '<text x="40" y="18" text-anchor="middle" font-family="Barlow Condensed,sans-serif" font-weight="700" font-size="11" letter-spacing="1.2" fill="var(--accent)">SANWALIYA</text>' : ""}
    <rect x="2" y="34" width="112" height="4.5" rx="1" fill="#1A2233"/>
    <rect x="80" y="0" width="3" height="12" rx="1.5" fill="#8A93A3"/>
    <path d="M80 11h17l11 13h6c3 0 4 1.5 4 4v7H80z" fill="var(--accent)"/>
    <path d="M84 15h11l7 9H84z" fill="#CFE3F3"/>
    <rect x="114" y="28.5" width="4" height="3" rx="1" fill="#FFD66B"/>
    <rect x="112" y="34.5" width="7" height="3.5" rx="1" fill="#1A2233"/>
    ${wheel(20)}${wheel(37)}${wheel(98)}
  </svg>`;
}
function initTrucks() {
  document.querySelectorAll(".road-truck").forEach((el) => { el.innerHTML = truckSVG("", true, true); });
  document.querySelectorAll(".scroll-road .scroll-truck").forEach((el) => { el.outerHTML = truckSVG("scroll-truck", false, false); });
  document.querySelectorAll("#trkTruckIcon svg").forEach((el) => { el.outerHTML = truckSVG("", false, false); });
}

/* ================= TEAM SOCIAL ICONS (URLs live in index.html -> window.TEAM_LINKS) ================= */
function teamLinks(p) {
  const links = (window.TEAM_LINKS && window.TEAM_LINKS[p.name]) || {};
  return [["linkedin", "LinkedIn"], ["instagram", "Instagram"]].map(([k, label]) => {
    const url = String(links[k] || "").trim();
    const ok = /^https?:\/\//i.test(url);
    const aria = `${label}: ${p.name}`;
    return `<a class="social-btn ${k}" aria-label="${escapeHtml(aria)}" title="${escapeHtml(aria)}" ` +
      (ok ? `href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer"` : `href="#" data-unset="${escapeHtml(aria)}"`) +
      `><svg class="icon" aria-hidden="true"><use href="#i-${k}" /></svg></a>`;
  }).join("");
}

/* ================= NAV SCROLL-SPY (liquid glass pill follows the section in view) ================= */
function initNavSpy() {
  const nav = $("navLinks");
  const pill = nav.querySelector(".nav-pill");
  const items = Array.from(nav.querySelectorAll("a[href^='#']:not(.nav-cta)"))
    .map((a) => ({ a, el: document.querySelector(a.getAttribute("href")) })).filter((i) => i.el);
  let current = null, queued = false, placed = false;

  const place = () => {
    if (!pill || !current || getComputedStyle(pill).display === "none") return;
    if (!placed) { pill.style.transition = "none"; }
    Object.assign(pill.style, { left: current.offsetLeft + "px", top: current.offsetTop + "px", width: current.offsetWidth + "px", height: current.offsetHeight + "px", opacity: 1 });
    if (!placed) { placed = true; requestAnimationFrame(() => requestAnimationFrame(() => { pill.style.transition = ""; })); }
  };
  const pick = () => {
    queued = false;
    const y = window.innerHeight * 0.4;
    let found = null;
    items.forEach((i) => { if (i.el.getBoundingClientRect().top <= y) found = i.a; });
    if (found === current) return;
    current = found;
    items.forEach((i) => {
      const on = i.a === current;
      i.a.classList.toggle("is-active", on);
      if (on) i.a.setAttribute("aria-current", "true"); else i.a.removeAttribute("aria-current");
    });
    if (!pill) return;
    if (!current) { pill.style.opacity = 0; return; }
    pill.classList.remove("go"); void pill.offsetWidth; pill.classList.add("go"); /* squish-and-settle */
    place();
  };
  window.updateNavPill = place;
  window.addEventListener("scroll", () => { if (!queued) { queued = true; requestAnimationFrame(pick); } }, { passive: true });
  window.addEventListener("resize", place);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(place);
  pick();
}
/* ================= VISITOR STATS ================= */
function initVisitorStats() {
  if (!window.firebase) return;
  firebase.initializeApp({
    apiKey: "AIzaSyB1ZUxuzAZAlal7VDVNOHUmIAh_OdlC134",
    authDomain: "sanwaliya-translinks.firebaseapp.com",
    databaseURL: "https://sanwaliya-translinks-default-rtdb.asia-southeast1.firebasedatabase.app",
    projectId: "sanwaliya-translinks",
    appId: "1:178682750304:web:e169f9cfac0d5a2ef5aa05"
  });
  const db = firebase.database();

  const me = db.ref("live").push();
  db.ref(".info/connected").on("value", (s) => {
    if (s.val()) { me.onDisconnect().remove(); me.set(true); }
  });
  db.ref("live").on("value", (s) => { $("liveCount").textContent = s.numChildren(); });

  const totalRef = db.ref("totalVisitors");
  let counted = false;
  try { counted = !!localStorage.getItem("stl_counted"); } catch (e) {}
  if (!counted) {
    totalRef.transaction((n) => (n || 0) + 1, (err, committed) => {
      if (!err && committed) { try { localStorage.setItem("stl_counted", "1"); } catch (e) {} }
    });
  }
  totalRef.on("value", (s) => {
    $("totalCount").textContent = (s.val() || 0).toLocaleString("en-IN");
  });
}